export const meta = {
  name: "review-diff",
  description:
    "Review one change with independent holyagent reviewers side by side and merge their blockers",
  phases: [{ title: "Review", detail: "one reviewer per Assignment" }],
}
// Generated by packages/integrations/claude/build.ts from packages/integrations/claude/src/workflows/review-diff.js and packages/integrations/claude/src/workflows/shared.js; edit the source and rebuild.
// The report every specialist returns, and the call that runs one dispatched Assignment.
const REPORT = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["done", "partial", "blocked"] },
    changed_paths: { type: "array", items: { type: "string" } },
    checks: {
      type: "array",
      items: {
        type: "object",
        properties: { command: { type: "string" }, exit: { type: "integer" } },
        required: ["command", "exit"],
      },
    },
    blockers: { type: "array", items: { type: "string" } },
    notes: { type: "array", items: { type: "string" } },
    evidence: {
      type: "array",
      items: {
        type: "object",
        properties: { key: { type: "string" }, support: { type: "string" } },
        required: ["key", "support"],
      },
    },
  },
  required: ["status", "changed_paths", "checks", "blockers", "notes", "evidence"],
}

const REPORT_REQUEST =
  "\n\nReturn your report as the structured output, not as text. Give each evidence line as an evidence entry: key is the criterion text or evidence label exactly as written, support is what shows it. List every check you ran in checks, and anything left undone in blockers."

// An entry is {id, agent, model, effort, prompt} as `assignment dispatch` prints it.
const runEntry = (entry, phase, addition = "") =>
  agent(entry.prompt + addition + REPORT_REQUEST, {
    agentType: entry.agent.includes(":") ? entry.agent : "holyagent:" + entry.agent,
    model: entry.model,
    effort: entry.effort,
    schema: REPORT,
    label: entry.id,
    phase,
  })

const change = typeof args.change === "string" ? args.change : JSON.stringify(args.change)
// A barrier is right here: the blockers are merged across all the reviewers.
const results = await parallel(
  args.reviewers.map(
    (entry) => () => runEntry(entry, "Review", "\n\nChange under review: " + change),
  ),
)
const merged = new Map()
args.reviewers.forEach((entry, index) => {
  for (const blocker of results[index]?.blockers ?? []) {
    const key = blocker.toLowerCase().replace(/\s+/g, " ").trim()
    const known = merged.get(key) ?? { blocker, reviewers: [] }
    if (!known.reviewers.includes(entry.id)) known.reviewers.push(entry.id)
    merged.set(key, known)
  }
})
return {
  reviewers: args.reviewers.map((entry, index) => ({
    id: entry.id,
    report: results[index] ?? null,
  })),
  blockers: [...merged.values()],
}
